import json
from datetime import timedelta

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
sensor_ids = [s.id for s in sensors]
last_readings_map = {}

if sensors:
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for sid, mtime in cr.fetchall():
        last_readings_map[sid] = mtime

plan = []

for sensor in sensors:
    device = sensor.device_id
    try:
        scfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except:
        scfg = {}

    try:
        dcfg = json.loads(device.remotecontrol_params or '{}') or {}
    except:
        dcfg = {}

    sensor_name = scfg.get('sensor_id', '').strip()
    if not sensor_name:
        continue

    start_cfg = scfg.get('start_date') or dcfg.get('start_date')
    last_m = last_readings_map.get(sensor.id)

    if last_m:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_m)
            )
        except:
            initial_date = str(last_m)[:10]
    else:
        if start_cfg:
            initial_date = start_cfg[:10]
        else:
            initial_date = '2025-01-01'

    # Resolve table and columns directly from sensor params (same pattern as alsambo)
    table = scfg.get('table', '').strip()
    value_field = scfg.get('value_field', '').strip()
    time_field = scfg.get('time_field', 'time').strip() or 'time'

    if not table or not value_field:
        continue  # skip: required params missing

    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'sensor_name': sensor_name,
        'table': table,
        'value_field': value_field,
        'time_field': time_field,
        'initial_date': initial_date,
    })

bag['electrosegura_plan'] = plan
bag['electrosegura_plan_count'] = len(plan)

# Create attachment with the plan for debugging
plan_json = json.dumps(plan, indent=2, ensure_ascii=False, default=str)
plan_b64 = base64.b64encode(plan_json.encode('utf-8'))
plan_fname = 'electrosegura_plan_%s.json' % fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')

plan_att = env['ir.attachment'].create({
    'name': plan_fname,
    'datas_fname': plan_fname,
    'datas': plan_b64,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id
})

Remote.message_post(
    body='[Electrosegura] Plan built: %s sensors to sync' % len(plan),
    attachment_ids=[plan_att.id]
)

import pyodbc from datetime import datetime
Remote = self.remote_id plan = bag.get('electrosegura_plan') or []
rows = [] errors = []
try: cfg = json.loads(Remote.connection_params or '{}') or {} driver = cfg.get('driver', 'MariaDB Unicode').strip() server = cfg.get('server', '').strip() port = cfg.get('port', '3306') database = cfg.get('database', '').strip() uid = cfg.get('uid', '').strip() pwd = cfg.get('pwd', '').strip()
if not all([server, database, uid]): raise Exception("Missing required connection parameters")
connection_string = ( "DRIVER={%s};" "SERVER=%s;" "PORT=%s;" "DATABASE=%s;" "UID=%s;" "PWD=%s;" ) % (driver, server, port, database, uid, pwd)
conn = pyodbc.connect(connection_string) cursor = conn.cursor()
for item in plan: sensor_id = item['sensor_id'] device_id = item['device_id'] sensor_name = item['sensor_name'] table_name = item['table'] value_col = item['value_field'] time_col = item['time_field'] initial_date = item['initial_date']
try: query = """ SELECT name, %s, %s FROM %s WHERE name = ? AND %s >= ? ORDER BY %s ASC """ % (value_col, time_col, table_name, time_col, time_col)
cursor.execute(query, (sensor_name, initial_date)) results = cursor.fetchall()
row_count = 0 for row in results: row_count += 1 name = row[0] if row[0] else '' value = row[1] timestamp = row[2]
if hasattr(timestamp, 'strftime'): ts = timestamp.strftime('%Y-%m-%d %H:%M:%S') else: ts = str(timestamp)
rows.append({ 'sensor_id': sensor_id, 'device_id': device_id, 'table': table_name, 'sensor_name': name, 'value': value, 'timestamp': ts, })
# Log info for debugging if row_count == 0: errors.append({ 'sensor_id': sensor_id, 'sensor_name': sensor_name, 'table': table_name, 'warning': 'No data found', 'query': query.replace('?', '%s') % (sensor_name, initial_date), 'initial_date': initial_date })
except Exception as e: errors.append({ 'sensor_id': sensor_id, 'sensor_name': sensor_name, 'table': table_name if 'table_name' in locals() else 'N/A', 'error': str(e), 'query': query if 'query' in locals() else 'N/A' })
cursor.close() conn.close()
except Exception as ex: errors.append({'fatal_error': str(ex)})
audit = { 'executed_at': fields.Datetime.now(), 'total_rows': len(rows), 'total_errors': len(errors), 'sample_rows': rows[:20], 'errors': errors[:10] if errors else [], }
audit_json = json.dumps(audit, indent=2, ensure_ascii=False, default=str) audit_b64 = base64.b64encode(audit_json.encode('utf-8')) fname = 'electrosegura_fetch_%s.json' % fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
att = env['ir.attachment'].create({ 'name': fname, 'datas_fname': fname, 'datas': audit_b64, 'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': Remote.id })
Remote.message_post( body='[Electrosegura] Fetch: %s rows, %s errors' % (len(rows), len(errors)), attachment_ids=[att.id] )
bag['electrosegura_rows'] = rows bag['electrosegura_fetch_errors'] = errors bag['electrosegura_fetch_filename'] = fname

import json
import pytz
from datetime import datetime

Remote = self.remote_id
Device = env['mdm.measurement.device']
Sensor = env['mdm.measurement.device.sensor']

def parse_value(v):
    """Parse numeric value from various formats."""
    if v is None:
        return None
    if isinstance(v, dict):
        for k in ('$numberDecimal', '$numberLong', '$numberInt'):
            if k in v:
                v = v[k]
                break
    if isinstance(v, str):
        v = v.strip().replace(',', '.')
        if v.lower() == 'nan':
            return None
        try:
            return float(v)
        except:
            return None
    if isinstance(v, (int, float)):
        return float(v)
    return None

rows = bag.get('electrosegura_rows') or []

total_processed = 0
total_upserts = 0
total_errors = 0
details = []

for r in rows:
    total_processed += 1

    sensor_id = r.get('sensor_id')
    device_id = r.get('device_id')
    timestamp = r.get('timestamp')
    value = parse_value(r.get('value'))

    if not sensor_id or not device_id or not timestamp or value is None:
        total_errors += 1
        if len(details) < 20:
            details.append({
                'sensor_id': sensor_id,
                'timestamp': timestamp,
                'value': value,
                'status': 'error',
                'error': 'Missing required fields'
            })
        continue

    sensor = Sensor.browse(sensor_id)
    device = Device.browse(device_id)

    if not sensor.exists() or not device.exists():
        total_errors += 1
        if len(details) < 20:
            details.append({
                'sensor_id': sensor_id,
                'device_id': device_id,
                'timestamp': timestamp,
                'status': 'error',
                'error': 'Sensor or device not found'
            })
        continue

    try:
        try:
            date_time_read = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
            date_time_read = pytz.timezone('Europe/Madrid').localize(date_time_read)
            date_time_read = date_time_read.astimezone(pytz.timezone('UTC'))
            ts_utc = date_time_read.strftime('%Y-%m-%d %H:%M:%S')
        except:
            ts_utc = timestamp

        Remote.upsert(
            'mdm.measurement.device.sensor.reading',
            {
                'sensor_id': sensor_id,
                'measurement_time': ts_utc,
            },
            {
                'value': value,
                'device_id': device_id,
            }
        )
        total_upserts += 1

        if len(details) < 20:
            details.append({
                'device_id': device_id,
                'sensor_id': sensor_id,
                'sensor_name': sensor.name,
                'timestamp': timestamp,
                'value': value,
                'status': 'success'
            })

    except Exception as e:
        total_errors += 1
        if len(details) < 20:
            details.append({
                'device_id': device_id,
                'sensor_id': sensor_id,
                'timestamp': timestamp,
                'value': value,
                'status': 'error',
                'error': str(e)
            })

success_rate = '0.0%'
if total_processed:
    success_rate = '%.1f%%' % (float(total_upserts) / float(total_processed) * 100.0)

bag['electrosegura_upsert_summary'] = {
    'executed_at': fields.Datetime.now(),
    'total_rows_processed': total_processed,
    'total_upserts': total_upserts,
    'total_errors': total_errors,
    'success_rate': success_rate,
}

bag['electrosegura_upsert_details'] = details

Remote.message_post(
    body='[Electrosegura] Upsert: %s processed, %s upserts, %s errors (success_rate=%s)' %
         (total_processed, total_upserts, total_errors, success_rate)
)
